import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int octal with unsigned value resolves', () => {
    assert.strictEqual(load('!!int 0o17'), 15);
  });
  it('explicit octal with sign still resolves', () => {
    assert.strictEqual(load('!!int -0o17'), -15);
  });
});

